---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Eval results: An eval run case by case, against the run before.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change eval-results.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './eval-results.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="eval-results" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="evr panel">
  <div class="evr-h"><div class="evr-ht"><b>Pricing copy evals</b><span class="muted evr-st">Copy agent · 8 cases · run 2h ago</span></div><button class="pill primary sm evr-run"><svg class="i xs"><use href="#i-play"/></svg>Run evals</button></div>
  <div class="evr-sum"><div class="evr-segs" aria-hidden="true"></div><div class="evr-nums"><span class="evr-pass num" aria-live="polite"></span><span class="tag evr-dl"></span></div></div>
  <div class="evr-tabs"><div class="seg2" role="group" aria-label="Show"><button aria-pressed="true" data-v="all">All <span class="n num"></span></button><button aria-pressed="false" data-v="fail">Failed <span class="n num"></span></button></div></div>
  <div class="evr-list" role="list" aria-label="Cases"></div>
  <p class="evr-none" hidden>No failed cases</p>
</div>
  </Fragment></div>
</div>
<script>
  import './eval-results.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Eval results ---------- */
/* an eval suite's latest run: one bar segment per case, the pass count against the run before, and the cases, all or
   just the failed ones. A failed case opens to show what was expected and what came back, with a fix that reruns it */
.evr{width:100%;max-width:440px;margin:0 auto;padding:6px;display:flex;flex-direction:column}
.evr-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);padding:var(--dm-s-2) 10px 10px}
.evr-ht{display:flex;flex-direction:column;min-width:0}
.evr-ht b{font-weight:500;font-size:14px}
.evr-st{font-size:12.5px}
.evr-run{flex:none}
.evr-run .spin{width:10px;height:10px}
.evr-sum{display:flex;flex-direction:column;gap:var(--dm-s-2);padding:var(--dm-s-3) 10px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.evr-segs{display:flex;gap:3px}
.evr-segs i{flex:1;height:6px;border-radius:3px;background:var(--dm-rail);transition:background .3s}
.evr-segs i.pass{background:var(--dm-ok)}
.evr-segs i.fail{background:var(--dm-bad-mark)}
.evr-segs i.run{background:var(--dm-accent-mark,var(--dm-accent));animation:evrrun 1s ease-in-out infinite}
@keyframes evrrun{50%{opacity:.4}}
.evr-nums{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);min-height:20px;font-size:13px}
.evr-dl:empty{display:none}
.evr-tabs{padding:10px var(--dm-s-1) var(--dm-s-1)}
.evr-tabs .n{color:var(--dm-muted);margin-left:2px}
.evr-tabs .n:empty{display:none}
.evr-list{display:flex;flex-direction:column}
/* a case folds away when the filter hides it, and stays hidden once shut so nothing measures it */
.evr-w.shut>div{visibility:hidden;transition:visibility 0s var(--dm-t)}
.evr-i{display:flex;flex-direction:column;border-radius:calc(10px * var(--dm-rk));transition:background .2s}
.evr-r{display:flex;align-items:center;gap:10px;width:100%;min-height:38px;padding:6px 10px;border-radius:calc(10px * var(--dm-rk));font-size:13px;text-align:left;color:var(--dm-fg)}
.evr-g{width:16px;height:16px;display:grid;place-items:center;flex:none;color:var(--dm-faint)}
.evr-g .spin{width:11px;height:11px;color:var(--dm-accent-fg,var(--dm-accent))}
.evr-i.pass .evr-g{color:var(--dm-ok)}
.evr-i.fail .evr-g{color:var(--dm-bad)}
.evr-n{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.evr-i.queued .evr-n{color:var(--dm-fg2)}
.evr-tm{font-size:12px;color:var(--dm-muted)}
.evr-ch{display:grid;color:var(--dm-muted)}
.evr-ch svg{transition:transform .32s var(--dm-ease)}
.evr-r[aria-expanded="false"] .evr-ch svg{transform:rotate(-90deg)}
.evr-i.fail{background:var(--dm-bad-bg)}.evr-i.fail :is(.evr-tm,.evr-kv .k){color:var(--dm-fg2)}
.evr-d.shut>div{visibility:hidden;transition:visibility 0s var(--dm-t)}
.evr-dd{display:flex;flex-direction:column;gap:var(--dm-s-1);padding:0 10px 10px 36px;font-size:12.5px}
.evr-kv{display:flex;gap:var(--dm-s-2)}
.evr-kv .k{width:58px;flex:none;color:var(--dm-muted)}
.evr-kv .bad{color:var(--dm-bad)}
.evr-fix{align-self:flex-start;margin-top:6px;background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-shadow)}
@media (hover:hover) and (pointer:fine){.evr-fix:hover{background:var(--dm-surface);box-shadow:var(--dm-shadow-pop)}}
.evr-none{margin:0;padding:10px;font-size:12.5px;color:var(--dm-muted)}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, DM, I, enter, html, seg, swap } from '../core/core.js';
DM.def('eval-results', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{play}', I('play','xs'));
  // eight checks on the pricing page's copy. The price check fails after the copy agent's latest edit, until it's fixed
  const K = [
    { n:'Names the Pro seat limit', tm:'0.6s' },
    { n:'Prices match the billing table', tm:'0.9s', bad:true, exp:'$24 a seat, billed yearly', got:'$29 a seat, billed yearly', src:'Billing table, Pro row' },
    { n:'Mentions the yearly discount', tm:'0.5s' },
    { n:'Makes no “unlimited” claims', tm:'0.4s' },
    { n:'Team plan lists SSO', tm:'0.5s' },
    { n:'Reads at grade 8 or below', tm:'0.7s' },
    { n:'One call to action per plan', tm:'0.5s' },
    { n:'Free plan says no card is needed', tm:'0.6s' }
  ].map(k => ({ ...k, s:'pass' }));
  const LAST = 8;
  const list = $('.evr-list', r), segs = $('.evr-segs', r), pass = $('.evr-pass', r), dl = $('.evr-dl', r), st = $('.evr-st', r), run = $('.evr-run', r), none = $('.evr-none', r), sg = $('.evr-tabs .seg2', r);
  const G = { run:'<span class="spin"></span>', pass:I('ok','xs'), fail:I('alert','xs'), queued:'<span class="dot"></span>' };
  let filter = 'all', busy = false, ran = false;
  K.forEach((k, i) => {
    k.w = html(`<div class="fold evr-w"><div><div class="evr-i" role="listitem"></div></div></div>`); k.el = $('.evr-i', k.w); k.i = i; list.appendChild(k.w);
    k.seg = document.createElement('i'); segs.appendChild(k.seg);
  });
  // a case's row: a failed one is a button that opens what was expected and what came back
  function paint(k, fresh){
    const open = k.s === 'fail' && k.open;
    k.el.className = 'evr-i ' + k.s;
    const g = `<span class="evr-g">${G[k.s]}</span><span class="evr-n">${k.n}</span><span class="evr-tm num">${k.s === 'pass' || k.s === 'fail' ? k.tm : ''}</span>`;
    k.el.innerHTML = k.s === 'fail'
      ? `<button class="evr-r" aria-expanded="${!!open}">${g}<span class="evr-ch">${I('chev-d','xs')}</span></button><div class="fold evr-d${open ? '' : ' shut'}"><div><div class="evr-dd"><span class="evr-kv"><span class="k">Expected</span><span>${k.exp}</span></span><span class="evr-kv"><span class="k">Got</span><span class="bad">${k.got}</span></span><span class="evr-kv"><span class="k">Source</span><span>${k.src}</span></span><button class="pill sm evr-fix">Use $24 and rerun</button></div></div></div>`
      : `<div class="evr-r">${g}</div>`;
    if (k.s === 'fail'){
      const d = $('.evr-d', k.el); d.inert = !open;
      $('.evr-r', k.el).onclick = () => { k.open = !k.open; $('.evr-r', k.el).setAttribute('aria-expanded', k.open); d.classList.toggle('shut', !k.open); d.inert = !k.open; };
      $('.evr-fix', k.el).onclick = () => fix(k);
    }
    if (fresh) enter($('.evr-g', k.el));
    k.seg.className = k.s;
  }
  function counts(){
    const p = K.filter(k => k.s === 'pass').length, f = K.filter(k => k.s === 'fail').length, done = K.every(k => k.s === 'pass' || k.s === 'fail');
    swap(pass, done ? `${p} of ${K.length} passed` : busy ? `Running ${K.filter(k => k.s === 'pass' || k.s === 'fail').length + 1} of ${K.length}` : 'Running the case again');
    const d = !ran || !done ? '' : p < LAST ? `${LAST - p} fewer than the last run` : 'All passing';
    if (dl.textContent !== d){ dl.textContent = d; dl.className = 'tag evr-dl ' + (p < LAST ? 'bad' : 'ok'); if (d) enter(dl); }
    $('[data-v="all"] .n', sg).textContent = K.length; $('[data-v="fail"] .n', sg).textContent = f;
    show();
  }
  // All shows every case; Failed folds the others away
  function show(){
    K.forEach(k => { const on = filter === 'all' || k.s === 'fail'; k.w.classList.toggle('shut', !on); k.w.inert = !on; });
    none.hidden = !(filter === 'fail' && !K.some(k => k.s === 'fail'));
  }
  seg(sg, v => { filter = v; show(); });
  K.forEach(k => paint(k)); counts();
  // a run checks the cases one after another; the price check fails until the copy is fixed
  run.onclick = () => c.run(async () => {
    if (busy) return; busy = true; ran = true; run.disabled = true; run.innerHTML = '<span class="spin"></span>Running';
    K.forEach(k => { k.s = 'queued'; k.open = false; paint(k); }); counts();
    for (const k of K){
      k.s = 'run'; paint(k, true); counts();
      await c.wait(500);
      k.s = k.bad ? 'fail' : 'pass'; paint(k, true); counts();
    }
    busy = false; run.disabled = false; run.innerHTML = I('play','xs') + 'Run again'; swap(st, 'Copy agent · 8 cases · run just now');
  });
  // the fix changes the copy to the billing table's price and runs that case again
  function fix(k){
    if (busy) return;
    c.run(async () => {
      k.bad = false; k.open = false; k.s = 'run'; paint(k, true); counts();
      await c.wait(1000);
      k.s = 'pass'; paint(k, true); counts();
    });
  }
  // the preview's story: run the evals, see one fail against the last run, open it, take the fix, and see all eight pass
  c.story(async s => {
    await s.beat(3);
    await s.tap(run); s.away();
    await s.until(() => !busy); await s.beat(3);
    await s.tap($('[data-v="fail"]', sg)); s.away(); await s.beat(2);
    await s.tap($('.evr-i.fail .evr-r', r)); s.away(); await s.beat(3);
    await s.tap($('.evr-fix', r)); s.away();
    await s.until(() => K.every(k => k.s === 'pass')); await s.beat(2);
    await s.tap($('[data-v="all"]', sg)); s.away(); await s.beat(2);
  });
});
